<?php if($u['role']==='seeker'):?><section id="resumes"><h2>Your résumés</h2><p>Keep different versions for different roles. Each application keeps the version you selected.</p><form method="post" enctype="multipart/form-data"><?=csrf()?><input type="hidden" name="action" value="upload-resumes"><label for="resumes-files">Upload PDF résumés</label><input id="resumes-files" type="file" name="resumes[]" accept="application/pdf,.pdf" multiple required aria-describedby="resume-help"><small id="resume-help">Up to five PDFs per upload, 5 MB each. Keep up to ten active résumés. Files are shared only with employers you apply to.</small><button class="button">Upload résumés ↗</button></form><?php $resumes=query('SELECT * FROM resumes WHERE user_id=? AND is_active=1 ORDER BY id DESC',[$u['id']])->fetchAll();if(!$resumes):?><p>No résumés uploaded yet.</p><?php endif;foreach($resumes as $resume):?><article class="application"><h3><?=h($resume['label'])?></h3><p><?=h($resume['original_name'])?> · <?=h(round($resume['size_bytes']/1024))?> KB</p><a class="text-link" href="resume.php?id=<?=h($resume['id'])?>">Download PDF ↗</a><form method="post"><?=csrf()?><input type="hidden" name="action" value="archive-resume"><input type="hidden" name="resume_id" value="<?=h($resume['id'])?>"><button class="text-button">Archive this version</button></form></article><?php endforeach;?></section><?php endif;?>
